function isBadUA() {
  var gUA = (navigator.userAgent + "\n" + document.referrer).toLowerCase();
  return gUA.indexOf("windows nt 5.0") > -1 || gUA.indexOf("windows 2000") > -1 ? !0 : gUA.indexOf("windows nt 5.1") > -1 || gUA.indexOf("windows xp") > -1 ? !0 : gUA.indexOf("windows nt 5.2") > -1 || gUA.indexOf("windows 2003") > -1 ? !0 : gUA.indexOf("windows nt 6.0") > -1 || gUA.indexOf("windows vista") > -1 ? !0 : /360se|360ee|qihu|360chrome|360|haosou|so.com/.test(gUA) ? !0 : !1;
}
if (isBadUA()) {
  $("#Load").prepend("<h2 style=\"margin-bottom: -80px;z-index:1060;position: relative;\" class=\"alert alert-warning text-center\">你使用了XP系统或者360搜索？→<a class=\"alert-link\" href=\"http://shang.qq.com/wpa/qunwpa?idkey=ce3ae345ee9c68ea75f5b66be2f35b94c759be05c9678f9226013efdbec3c79b\" title=\"想看电影\">点击这里</a>←告诉我们此判断是否正确<br /> <span class=\"text-muted text-center\">（其实我们并不在乎，只是想让你加下QQ群）</span></h2>");
  intDelay = 0;
}
